package duckdb

import (
	"math"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/duckdb/duckdb-go/v2/mapping"
)

func TestUUIDValueBindRoundTrip(t *testing.T) {
	db := openDbWrapper(t, ``)
	defer closeDbWrapper(t, db)
	_, err := db.Exec(`CREATE TABLE t (ids UUID[], arr UUID[1], s STRUCT(a UUID), m MAP(UUID, UUID))`)
	require.NoError(t, err)
	for _, want := range []string{
		"123e4567-e89b-12d3-a456-426614174000",
		"923e4567-e89b-12d3-a456-426614174000",
	} {
		t.Run(want, func(t *testing.T) {
			var u UUID
			require.NoError(t, u.Scan(want))
			_, err := db.Exec(`DELETE FROM t`)
			require.NoError(t, err)
			_, err = db.Exec(`INSERT INTO t VALUES (?, ?, ?, ?)`,
				[]UUID{u}, [1]UUID{u}, map[string]any{"a": u}, Map{u: u})
			require.NoError(t, err)
			var list, array, st, mapKey, mapValue string
			require.NoError(t, db.QueryRow(`SELECT ids[1]::VARCHAR, arr[1]::VARCHAR, s.a::VARCHAR,
				map_keys(m)[1]::VARCHAR, map_values(m)[1]::VARCHAR FROM t`).
				Scan(&list, &array, &st, &mapKey, &mapValue))
			for name, got := range map[string]string{
				"list": list, "array": array, "struct": st, "map key": mapKey, "map value": mapValue,
			} {
				t.Run(name, func(t *testing.T) { require.Equal(t, want, got) })
			}
			t.Run("untyped", func(t *testing.T) {
				var got string
				require.NoError(t, db.QueryRow(`SELECT x::VARCHAR FROM (SELECT ? AS x)`, u).Scan(&got))
				require.Equal(t, want, got)
			})
		})
	}
}

func TestCreateRejectedValues(t *testing.T) {
	doubleType := mapping.CreateLogicalType(TYPE_DOUBLE)
	defer mapping.DestroyLogicalType(&doubleType)
	intType := mapping.CreateLogicalType(TYPE_INTEGER)
	defer mapping.DestroyLogicalType(&intType)
	mapType := mapping.CreateMapType(doubleType, intType)
	defer mapping.DestroyLogicalType(&mapType)

	tests := []struct {
		name   string
		create func() (mapping.Value, error)
	}{
		{
			name: "invalid UTF-8 primitive",
			create: func() (mapping.Value, error) {
				return createPrimitiveValue(TYPE_VARCHAR, "\xff")
			},
		},
		{
			name: "duplicate map keys",
			create: func() (mapping.Value, error) {
				return createValue(mapType, OrderedMap{[]any{math.NaN(), math.NaN()}, []any{int32(1), int32(2)}})
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			v, err := tt.create()
			defer mapping.DestroyValue(&v)
			require.ErrorIs(t, err, errCreateValue)
		})
	}
}

func TestInferRejectedValues(t *testing.T) {
	tests := []struct {
		name string
		arg  any
	}{
		{name: "invalid UTF-8 primitive", arg: "\xff"},
		{name: "invalid UTF-8 list element", arg: []string{"\xff"}},
		{name: "invalid UTF-8 array element", arg: [2]string{"\xff", "ok"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			lt, v, err := inferLogicalTypeAndValue(tt.arg)
			defer mapping.DestroyLogicalType(&lt)
			defer mapping.DestroyValue(&v)
			require.ErrorIs(t, err, errCreateValue)
		})
	}
}

package duckdb

import (
	"testing"
	"time"
)

func benchmarkSetChunkValueType[T any](b *testing.B, typ Type, values []T) {
	b.Helper()
	chunk := newTypeTestChunk(b, typ)

	b.ReportAllocs()
	b.ResetTimer()
	for i := range b.N {
		if err := SetChunkValue(chunk, 0, 0, values[i%len(values)]); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkSetRowValueDispatch(b *testing.B) {
	chunk := newTypeTestChunk(b, TYPE_BIGINT)
	row := Row{chunk: &chunk}

	b.ReportAllocs()
	b.ResetTimer()
	// Vary the value so interface conversion cannot reuse boxed constants.
	for i := range b.N {
		if err := SetRowValue(row, 0, int64(i)); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkDataChunkSetValueDispatch(b *testing.B) {
	chunk := newTypeTestChunk(b, TYPE_BIGINT)
	values := []any{int64(1_000_000), int64(2_000_000)}

	b.ReportAllocs()
	b.ResetTimer()
	for i := range b.N {
		if err := chunk.SetValue(0, 0, values[i%len(values)]); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkSetChunkValueDispatchTypes(b *testing.B) {
	b.Run("BIGINT_from_int64", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_BIGINT, []int64{1_000_000, 2_000_000})
	})
	b.Run("BIGINT_from_int", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_BIGINT, []int{1_000_000, 2_000_000})
	})
	b.Run("VARCHAR_from_string", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_VARCHAR, []string{"one", "two"})
	})
	b.Run("VARCHAR_from_bytes", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_VARCHAR, [][]byte{[]byte("one"), []byte("two")})
	})
	b.Run("BLOB_from_string", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_BLOB, []string{"one", "two"})
	})
	b.Run("TIMESTAMP_from_time", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_TIMESTAMP, []time.Time{
			time.Unix(1, 0),
			time.Unix(2, 0),
		})
	})
	b.Run("INTERVAL", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_INTERVAL, []Interval{
			{Days: 1},
			{Days: 2},
		})
	})
	b.Run("UUID", func(b *testing.B) {
		benchmarkSetChunkValueType(b, TYPE_UUID, []UUID{
			{1},
			{2},
		})
	})
}

