package duckdb

import (
	"context"
	"database/sql"
	"fmt"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/duckdb/duckdb-go/v2/mapping"
)

// getEnumCGO is the original (pre-optimization) implementation, preserved
// here solely for benchmarking purposes. It creates and destroys a
// LogicalType via CGO on every cell read.
func (vec *vector) getEnumCGO(rowIdx mapping.IdxT) string {
	var idx mapping.IdxT
	switch vec.internalType {
	case TYPE_UTINYINT:
		idx = mapping.IdxT(getPrimitive[uint8](vec, rowIdx))
	case TYPE_USMALLINT:
		idx = mapping.IdxT(getPrimitive[uint16](vec, rowIdx))
	case TYPE_UINTEGER:
		idx = mapping.IdxT(getPrimitive[uint32](vec, rowIdx))
	case TYPE_UBIGINT:
		idx = mapping.IdxT(getPrimitive[uint64](vec, rowIdx))
	}

	logicalType := mapping.VectorGetColumnType(vec.vec)
	defer mapping.DestroyLogicalType(&logicalType)
	return mapping.EnumDictionaryValue(logicalType, idx)
}

func setupEnumBench(b *testing.B, rowCount int) (*sql.DB, *Connector) {
	b.Helper()
	c := newConnectorWrapper(b, ``, nil)
	db := sql.OpenDB(c)

	_, err := db.Exec(`CREATE TYPE bench_enum AS ENUM ('alpha', 'beta', 'gamma', 'delta', 'epsilon')`)
	require.NoError(b, err)
	_, err = db.Exec(`CREATE TABLE bench_enum_tbl (val bench_enum)`)
	require.NoError(b, err)
	_, err = db.Exec(fmt.Sprintf(`
		INSERT INTO bench_enum_tbl
		SELECT (ARRAY['alpha','beta','gamma','delta','epsilon'])[1 + (i %% 5)]
		FROM generate_series(0, %d) AS t(i)
	`, rowCount-1))
	require.NoError(b, err)

	return db, c
}

var benchmarkEnumSink string

// BenchmarkEnumGetValue compares the optimized enumDict path (new)
// against the original CGO-per-cell path (old).
//
// Both sub-benchmarks iterate the same fetched vectors,
// differing only in the getter function called per cell:
//   - Dict: vec.getEnum()    — single []string slice index lookup
//   - CGO:  vec.getEnumCGO() — VectorGetColumnType + EnumDictionaryValue + DestroyLogicalType
func BenchmarkEnumGetValue(b *testing.B) {
	for _, n := range []int{10_000, 100_000} {
		b.Run(fmt.Sprintf("Dict/N=%d", n), func(b *testing.B) {
			benchEnumVector(b, n, false)
		})
		b.Run(fmt.Sprintf("CGO/N=%d", n), func(b *testing.B) {
			benchEnumVector(b, n, true)
		})
	}
}

func benchEnumVector(b *testing.B, rowCount int, useCGO bool) {
	b.Helper()
	db, c := setupEnumBench(b, rowCount)
	defer closeDbWrapper(b, db)
	defer closeConnectorWrapper(b, c)

	mc, err := c.Connect(context.Background())
	require.NoError(b, err)
	conn := mc.(*Conn)
	defer func() {
		require.NoError(b, conn.Close())
	}()

	b.ResetTimer()

	for b.Loop() {
		stmt, e := conn.Prepare(`SELECT val FROM bench_enum_tbl`)
		require.NoError(b, e)
		s := stmt.(*Stmt)

		dkRows, e := s.QueryContext(context.Background(), nil)
		require.NoError(b, e)
		r := dkRows.(*rows)

		count := 0

		for {
			duckChunk := mapping.FetchChunk(r.res)
			if duckChunk.Ptr == nil {
				break
			}

			var chunk DataChunk
			require.NoError(b, chunk.initFromDuckDataChunk(duckChunk, false))

			vec := &chunk.columns[0]
			if useCGO {
				for rowIdx := range chunk.size {
					benchmarkEnumSink = vec.getEnumCGO(mapping.IdxT(rowIdx))
				}
			} else {
				for rowIdx := range chunk.size {
					benchmarkEnumSink, e = vec.getEnum(mapping.IdxT(rowIdx))
					require.NoError(b, e)
				}
			}
			count += chunk.size
			chunk.close()
		}

		require.NoError(b, dkRows.Close())
		require.NoError(b, s.Close())
		require.Equal(b, rowCount, count)
	}

	b.StopTimer()
}

package duckdb

import (
	"context"
	"database/sql"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestMultiStatementParameters(t *testing.T) {
	intermediateError := errParametersBeforeLastStmt.Error()
	for _, method := range []string{"exec", "query", "prepare"} {
		for _, tt := range []struct {
			name  string
			query string
			args  []any
			err   string
		}{
			{"first", `SET VARIABLE value = ?; SET VARIABLE later = 'reached';`, []any{"duck"}, intermediateError},
			{"middle", `SET VARIABLE earlier = 'camel'; SET VARIABLE value = ?; SET VARIABLE later = 'reached';`, []any{"duck"}, intermediateError},
			{"named", `SET VARIABLE value = $bird; SET VARIABLE later = 'reached';`, []any{sql.Named("bird", "duck")}, intermediateError},
			{"last", `SET VARIABLE earlier = 'camel'; SET VARIABLE value = ?;`, []any{"duck"}, ""},
			{"missing final argument", `SET VARIABLE earlier = 'camel'; SET VARIABLE value = ?;`, nil, "incorrect argument count for command: have 0 want 1"},
		} {
			t.Run(method+"/"+tt.name, func(t *testing.T) {
				db := openDbWrapper(t, ``)
				defer closeDbWrapper(t, db)
				ctx := context.Background()
				conn := openConnWrapper(t, db, ctx)
				defer closeConnWrapper(t, conn)

				var err error
				switch method {
				case "exec":
					_, err = conn.ExecContext(ctx, tt.query, tt.args...)
				case "query":
					var rows *sql.Rows
					rows, err = conn.QueryContext(ctx, tt.query, tt.args...)
					if rows != nil {
						closeRowsWrapper(t, rows)
					}
				case "prepare":
					var stmt *sql.Stmt
					stmt, err = conn.PrepareContext(ctx, tt.query)
					if err == nil {
						defer closePreparedWrapper(t, stmt)
						_, err = stmt.ExecContext(ctx, tt.args...)
						// database/sql checks prepared statement arity before the driver.
						if tt.name == "missing final argument" {
							require.EqualError(t, err, "sql: expected 1 arguments, got 0")
							return
						}
					}
				}
				if tt.err != "" {
					require.EqualError(t, err, tt.err)
					var later sql.NullString
					require.NoError(t, conn.QueryRowContext(ctx, `SELECT getvariable('later')`).Scan(&later))
					require.False(t, later.Valid, "statements after the error must not execute")
					return
				}
				require.NoError(t, err)
				var value string
				require.NoError(t, conn.QueryRowContext(ctx, `SELECT getvariable('value')`).Scan(&value))
				require.Equal(t, "duck", value)
			})
		}
	}
}

func TestGetTableNames(t *testing.T) {
	db := openDbWrapper(t, ``)
	defer closeDbWrapper(t, db)

	conn := openConnWrapper(t, db, context.Background())
	defer closeConnWrapper(t, conn)

	tests := []struct {
		name           string
		query          string
		qualified      bool
		expectedTables []string
		expectedError  string
	}{
		{
			name:           "valid query with multiple tables, qualified",
			query:          `SELECT * FROM schema1.table1, catalog3."schema.2"."table.2"`,
			qualified:      true,
			expectedTables: []string{"schema1.table1", `catalog3."schema.2"."table.2"`},
		},
		{
			name:           "valid query with multiple tables, unqualified",
			query:          `SELECT * FROM schema1.table1, catalog3."schema.2"."table.2"`,
			qualified:      false,
			expectedTables: []string{"table1", "table.2"},
		},
		{
			name:           "valid query with no tables",
			query:          "SELECT 1 as num",
			expectedTables: nil,
		},
		{
			name:          "invalid query syntax",
			query:         "SELECT * FROM WHERE",
			expectedError: "Parser Error: syntax error at or near \"WHERE\"",
		},
		{
			name:          "empty query",
			query:         "",
			expectedError: "empty query",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tableNames, err := GetTableNames(conn, tt.query, tt.qualified)
			if tt.expectedError != "" {
				require.Contains(t, err.Error(), tt.expectedError)
				assert.Nil(t, tableNames)
			} else {
				require.NoError(t, err)
				assert.ElementsMatch(t, tt.expectedTables, tableNames)
			}
		})
	}
}

package duckdb

import (
	"context"
	"database/sql/driver"
	"fmt"
	"strings"
	"testing"
	"unicode"

	"github.com/stretchr/testify/require"
)

type varcharTransformBenchmarkUDF struct {
	info      TypeInfo
	useVector bool
}

func (udf *varcharTransformBenchmarkUDF) Config() ScalarFuncConfig {
	return ScalarFuncConfig{
		InputTypeInfos: []TypeInfo{udf.info},
		ResultTypeInfo: udf.info,
	}
}

func (udf *varcharTransformBenchmarkUDF) Executor() ScalarFuncExecutor {
	if !udf.useVector {
		return ScalarFuncExecutor{
			RowExecutor: func(values []driver.Value) (any, error) {
				return transformBenchmarkVarchar(values[0].(string)), nil
			},
		}
	}

	return ScalarFuncExecutor{
		ChunkContextExecutor: func(_ context.Context, state *ChunkIteratorState) error {
			inputVector, err := state.GetInputChunk().GetVector(0)
			if err != nil {
				return err
			}
			input, err := GetVectorView[string](inputVector)
			if err != nil {
				return err
			}
			output, err := GetVectorWriter[string](state.GetResultVector())
			if err != nil {
				return err
			}

			for row := range input.Len() {
				value, valid, err := input.GetValueBorrowed(row)
				if err != nil {
					return err
				}
				if !valid {
					// Default NULL handling sets this result to NULL after the callback.
					continue
				}
				if err = output.Set(row, transformBenchmarkVarchar(value)); err != nil {
					return err
				}
			}
			return nil
		},
	}
}

func transformBenchmarkVarchar(value string) string {
	value = strings.TrimSpace(value)
	return strings.Map(func(r rune) rune {
		if r == '-' {
			return '_'
		}
		return unicode.ToUpper(r)
	}, value)
}

var varcharTransformBenchmarkSink int64

const varcharTransformBenchmarkRowCount = 2_000_000

func BenchmarkVarcharTransformUDF(b *testing.B) {
	db := openDbWrapper(b, ``)
	defer closeDbWrapper(b, db)
	conn := openConnWrapper(b, db, context.Background())
	defer closeConnWrapper(b, conn)
	_, err := conn.ExecContext(context.Background(), `SET threads = 1`)
	require.NoError(b, err)

	info := mustTypeInfo(b, TYPE_VARCHAR)
	require.NoError(b, RegisterScalarUDF(conn, "varchar_rows_transform", &varcharTransformBenchmarkUDF{
		info: info,
	}))
	require.NoError(b, RegisterScalarUDF(conn, "varchar_vector_transform", &varcharTransformBenchmarkUDF{
		info:      info,
		useVector: true,
	}))

	_, err = conn.ExecContext(context.Background(), fmt.Sprintf(`
		CREATE TABLE varchar_transform_benchmark AS
		SELECT CASE i %% 6
			WHEN 0 THEN NULL::VARCHAR
			WHEN 1 THEN ''
			WHEN 2 THEN '  customer-' || i::VARCHAR || '-alpha  '
			WHEN 3 THEN repeat('duckdb-go-', 4) || i::VARCHAR
			WHEN 4 THEN '  München-' || i::VARCHAR || '-straße  '
			ELSE repeat('long-varchar-value-', 8) || i::VARCHAR
		END AS value
		FROM range(%d) values(i)
	`, varcharTransformBenchmarkRowCount))
	require.NoError(b, err)

	benchmarks := []struct {
		name     string
		function string
	}{
		{name: "RowExecutor", function: "varchar_rows_transform"},
		{name: "ChunkVector", function: "varchar_vector_transform"},
	}

	for _, benchmark := range benchmarks {
		b.Run(benchmark.name, func(b *testing.B) {
			query := `SELECT coalesce(sum(length(` + benchmark.function +
				`(value))), 0) FROM varchar_transform_benchmark`
			stmt, prepareErr := conn.PrepareContext(context.Background(), query)
			require.NoError(b, prepareErr)
			defer func() {
				require.NoError(b, stmt.Close())
			}()

			require.NoError(b, stmt.QueryRowContext(context.Background()).Scan(&varcharTransformBenchmarkSink))

			b.ReportAllocs()
			b.ResetTimer()
			for b.Loop() {
				if err := stmt.QueryRowContext(context.Background()).Scan(&varcharTransformBenchmarkSink); err != nil {
					b.Fatal(err)
				}
			}
			b.ReportMetric(varcharTransformBenchmarkRowCount, "rows/op")
		})
	}
}

package duckdb

import (
	"context"
	"testing"
	"unsafe"

	"github.com/stretchr/testify/require"

	"github.com/duckdb/duckdb-go/v2/mapping"
)

type appenderSpies struct {
	flush                bool
	clear                bool
	destroyAppenderCalls int
	destroyChunkCalls    int
	resetChunk           bool
	getChunkVector       bool
}

// stubAppenderMapping installs no-op/spy mapping hooks for appender cancellation tests.
func stubAppenderMapping(t *testing.T, flushState mapping.State, appenderErr string) *appenderSpies {
	t.Helper()

	spies := &appenderSpies{}
	patchVar(t, &mapping.Interrupt, func(_ mapping.Connection) {})

	// Spy hooks record the appender and chunk operations under test.
	patchVar(t, &mapping.AppenderFlush, func(_ mapping.Appender) mapping.State {
		spies.flush = true
		return flushState
	})
	patchVar(t, &mapping.AppenderError, func(_ mapping.Appender) string {
		return appenderErr
	})
	patchVar(t, &mapping.AppenderClear, func(_ mapping.Appender) mapping.State {
		spies.clear = true
		return mapping.StateSuccess
	})
	patchVar(t, &mapping.AppenderDestroy, func(_ *mapping.Appender) mapping.State {
		spies.destroyAppenderCalls++
		return mapping.StateSuccess
	})
	patchVar(t, &mapping.DestroyDataChunk, func(_ *mapping.DataChunk) {
		spies.destroyChunkCalls++
	})
	patchVar(t, &mapping.DataChunkReset, func(_ mapping.DataChunk) {
		spies.resetChunk = true
	})

	// Safety no-ops keep fake handles away from the C API if chunk reset is reached.
	patchVar(t, &mapping.DataChunkSetSize, func(_ mapping.DataChunk, _ mapping.IdxT) {})
	patchVar(t, &mapping.DataChunkGetVector, func(_ mapping.DataChunk, _ mapping.IdxT) mapping.Vector {
		spies.getChunkVector = true
		return mapping.Vector{}
	})
	patchVar(t, &mapping.VectorGetData, func(_ mapping.Vector) unsafe.Pointer {
		return nil
	})
	patchVar(t, &mapping.VectorEnsureValidityWritable, func(_ mapping.Vector) {})
	patchVar(t, &mapping.VectorGetValidity, func(_ mapping.Vector) unsafe.Pointer {
		return nil
	})
	return spies
}

func newStubAppender() *Appender {
	return &Appender{
		conn: &Conn{},
	}
}

func preCanceledContext() context.Context {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	return ctx
}

// The tests below patch package-level mapping hooks and must not run in parallel.
func TestAppenderFlushWithCancelPreCanceledAttemptsFlush(t *testing.T) {
	// This characterizes the fast success path; failure and interrupt handling are covered below.
	spies := stubAppenderMapping(t, mapping.StateSuccess, "")

	ctx := preCanceledContext()
	a := newStubAppender()

	require.NoError(t, a.flushWithCancel(ctx))
	require.True(t, spies.flush, "AppenderFlush should run when ctx is pre-canceled")
}

func TestAppenderCloseWithCancelPreCanceledFlushesAndCleansUp(t *testing.T) {
	// This characterizes the fast success path; failure and interrupt handling are covered below.
	spies := stubAppenderMapping(t, mapping.StateSuccess, "")

	ctx := preCanceledContext()
	a := newStubAppender()

	require.NoError(t, a.CloseWithCancel(ctx))
	require.True(t, spies.flush, "AppenderFlush should run when ctx is pre-canceled")
	require.False(t, spies.clear, "successful pre-canceled close should not clear flushed appender state")
	require.Equal(t, 1, spies.destroyAppenderCalls, "pre-canceled close should destroy the appender")
	require.Equal(t, 1, spies.destroyChunkCalls, "pre-canceled close should destroy the data chunk")
}

func TestAppenderFlushWithCancelPreCanceledFailureIncludesContext(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateError, "Invalid Input Error: appender failed")

	ctx := preCanceledContext()
	a := newStubAppender()

	err := a.flushWithCancel(ctx)
	require.ErrorIs(t, err, context.Canceled)
	require.ErrorContains(t, err, "appender failed")

	err = a.FlushWithCancel(ctx)
	require.ErrorIs(t, err, errAppenderFlush)
	require.ErrorIs(t, err, context.Canceled)
	require.ErrorContains(t, err, "appender failed")
	require.True(t, spies.flush, "AppenderFlush should run when ctx is pre-canceled")
}

func TestAppenderCloseWithCancelFlushFailureClearsWithoutResettingChunk(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateError, "Invalid Input Error: appender failed")

	ctx := preCanceledContext()
	a := newStubAppender()
	a.chunk.columns = make([]vector, 1)

	err := a.CloseWithCancel(ctx)
	require.ErrorIs(t, err, errAppenderClose)
	require.ErrorIs(t, err, context.Canceled)
	require.ErrorContains(t, err, "appender failed")
	require.True(t, spies.clear, "failed close should clear buffered appender state")
	require.False(t, spies.resetChunk, "failed close should not reset the destroyed data chunk")
	require.False(t, spies.getChunkVector, "failed close should not reinitialize vectors on the destroyed data chunk")
}

func TestAppenderCloseWithCancelFlushAndClearFailuresAreJoined(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateError, "Invalid Input Error: flush failed")

	var appenderErrorCalls int
	patchVar(t, &mapping.AppenderError, func(_ mapping.Appender) string {
		appenderErrorCalls++
		if appenderErrorCalls == 1 {
			return "Invalid Input Error: flush failed"
		}
		return "Invalid Input Error: clear failed"
	})
	patchVar(t, &mapping.AppenderClear, func(_ mapping.Appender) mapping.State {
		spies.clear = true
		return mapping.StateError
	})

	a := newStubAppender()

	err := a.CloseWithCancel(context.Background())
	require.ErrorIs(t, err, errAppenderClose)
	require.ErrorContains(t, err, "flush failed")
	require.ErrorContains(t, err, "clear failed")
	require.ErrorContains(t, err, "failed to clear appender's internal data")
	require.True(t, spies.clear, "failed close should still try to clear buffered appender state")
}

func TestAppenderCloseWithCancelAppendFailureIncludesError(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateSuccess, "Invalid Input Error: append failed")

	var appendCalled bool
	patchVar(t, &mapping.AppendDataChunk, func(_ mapping.Appender, _ mapping.DataChunk) mapping.State {
		appendCalled = true
		return mapping.StateError
	})

	a := newStubAppender()
	a.rowCount = 1
	a.chunk.columns = make([]vector, 1)

	err := a.CloseWithCancel(context.Background())
	require.ErrorIs(t, err, errAppenderClose)
	require.ErrorContains(t, err, "append failed")
	require.True(t, appendCalled, "CloseWithCancel should append buffered rows before flushing")
	require.Equal(t, 1, spies.destroyAppenderCalls, "append failure should still destroy the appender")
	require.Equal(t, 1, spies.destroyChunkCalls, "append failure should still destroy the data chunk")
}

func TestAppenderCloseWithCancelDestroyFailureReturnsError(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateSuccess, "")
	patchVar(t, &mapping.AppenderDestroy, func(_ *mapping.Appender) mapping.State {
		spies.destroyAppenderCalls++
		return mapping.StateError
	})

	a := newStubAppender()

	err := a.CloseWithCancel(context.Background())
	require.ErrorIs(t, err, errAppenderClose)
	require.Equal(t, 1, spies.destroyAppenderCalls, "failed destroy should only run once")
	require.Equal(t, 1, spies.destroyChunkCalls, "failed destroy should still follow data chunk cleanup")
}

func TestAppenderCloseWithCancelDoubleCloseDoesNotDestroyAgain(t *testing.T) {
	spies := stubAppenderMapping(t, mapping.StateSuccess, "")

	a := newStubAppender()

	require.NoError(t, a.CloseWithCancel(context.Background()))

	err := a.CloseWithCancel(context.Background())
	require.ErrorIs(t, err, errAppenderDoubleClose)
	require.Equal(t, 1, spies.destroyAppenderCalls, "double close should not destroy the appender again")
	require.Equal(t, 1, spies.destroyChunkCalls, "double close should not destroy the data chunk again")
}

package duckdb

